model_config.built_in_css:
/* =============================================
   word-edit-power · 词条修改异能
   --------------------------------------------------------------
   皮肤 = 「网文系统面板 / 词条状态栏」(呼应 description「词条面板」)
   base: 暖晨白 #f1efe9   is-dark:0(浅色 · 平台禁深色)
   accent: 鎏金(改字痕) #a9852e   次 accent: 系统墨蓝 #2b4260

   色板(全部写死 hex/rgba,零 var()):
   paper(底):#f1efe9  paper2:#dfdbd0  paper3:#c9cdd4  paper-card:#fbfaf7
   ink(墨·正文):#222a2c  ink-soft:#353f42  mut(次级):#6a7176  dim(弱):#8b8f8c
   gold(鎏金·accent):#a9852e  gold-deep:#8a6c22  gold-tint:rgba(169,133,46,.08)
   blue(系统墨蓝·次accent):#2b4260  blue-deep:#1d2f47  line:#222a2c
   字体: 'Noto Serif SC' 衬线(正文)

   正文字号: .markdown-body 1.3em · 衬线
   亮点① .sys →【叮】系统通告条 + .sysbar 每轮仪表条(天数·额度·性交数)
   亮点② 加载动画 → 内嵌 SVG-SMIL 金点脉动 + 光标闪(非 CSS 循环)
   亮点③ details=系统折叠栏(墨蓝 summary) · .pga=执行按钮(序号 CSS counter 右下描金水印 + 右上「执行」角标)
   亮点④ .tk → 词条面板(网文系统状态栏 · 每轮展开) · mark=被玩家改过的字(金高亮 · 永久)
   ⚠️ 全卡禁止一切左侧竖条(border-left accent),pre/blockquote/details/.pga 一律全框/顶部线/角标
   ============================================= */

pre{white-space:pre-wrap!important;word-wrap:break-word!important;font-family:'Noto Serif SC','Source Han Serif SC','PingFang SC',serif!important}

/* ===== 危险区域 ===== */
[class*="bg-[#F1CBCB]"],[class*="bg-[#c9e1e9]"]{display:none!important}

/* 代码块 pre —— 无左竖条,公文表全框 + 顶部线 */
.markdown-body pre{
  background:#fbfaf7!important;
  border:1px solid #222a2c!important;
  border-top:3px solid #2b4260!important;
  border-radius:0!important;
  padding:1em 1.2em!important;
  overflow-x:auto!important;
  font-size:17px!important;
  line-height:1.55!important;
  color:#222a2c!important;
  box-shadow:2px 2px 0 rgba(43,66,96,0.10),inset 0 0 22px rgba(43,66,96,0.04)!important
}
.markdown-body pre code{
  background:transparent!important;
  color:#222a2c!important;
  font-family:'Noto Serif SC','Courier New',serif!important
}
.markdown-body :not(pre)>code{
  background:rgba(169,133,46,0.08)!important;
  color:#a9852e!important;
  padding:0.16em 0.48em!important;
  border:1px solid rgba(169,133,46,0.30)!important;
  border-radius:0!important;
  font-size:0.92em!important;
  font-weight:700!important
}

/* details 折叠 —— 系统折叠栏,无左竖条,全框 + 系统墨蓝标题行 */
.markdown-body details{
  background:#fbfaf7!important;
  border:1px solid #222a2c!important;
  border-radius:0!important;
  margin:10px 0!important;
  overflow:hidden!important;
  transition:border-color 0.18s ease,box-shadow 0.18s ease!important
}
.markdown-body details[open]{
  border-color:#2b4260!important;
  box-shadow:3px 3px 0 rgba(43,66,96,0.16)!important
}
.markdown-body details summary{
  background:#c9cdd4!important;
  color:#1d2f47!important;
  padding:10px 14px 10px 40px!important;
  display:block!important;
  position:relative!important;
  border-bottom:2px solid #222a2c!important;
  cursor:pointer!important;
  font-weight:900!important;
  font-size:18px!important;
  letter-spacing:0.1em!important;
  list-style:none!important;
  user-select:none!important
}
.markdown-body details summary::before{
  content:'◈'!important;
  position:absolute!important;
  left:14px!important;
  top:50%!important;
  transform:translateY(-50%)!important;
  color:#a9852e!important;
  font-size:13px!important;
  transition:transform 0.2s ease,color 0.2s ease!important
}
.markdown-body details[open] summary::before{transform:translateY(-50%) rotate(90deg)!important;color:#8a6c22!important}
.markdown-body details summary::-webkit-details-marker{display:none!important}

/* 滚动条 */
::-webkit-scrollbar{width:9px!important;height:9px!important}
::-webkit-scrollbar-track{background:#c9cdd4!important;border-radius:0!important}
::-webkit-scrollbar-thumb{background:#8b8f8c!important;border-radius:0!important}
::-webkit-scrollbar-thumb:hover{background:#a9852e!important}

/* 占位符 + 选区 */
::placeholder{color:#8b8f8c!important;opacity:1!important}
::selection{background:rgba(169,133,46,0.16)!important;color:#8a6c22!important}

/* ⚠️ 输入框强制可见 —— bg+color+caret 三件套(公文纸底 + 墨字 + 朱红 caret) */
#ai-chat-input{
  background:#fbfaf7!important;
  color:#222a2c!important;
  caret-color:#a9852e!important;
  font-family:'Noto Serif SC','PingFang SC',serif!important
}
#ai-chat-bottom-input{
  background:#fbfaf7!important;
  color:#222a2c!important;
  caret-color:#a9852e!important;
  font-family:'Noto Serif SC','PingFang SC',serif!important
}
textarea.rc-textarea{
  background:#fbfaf7!important;
  color:#222a2c!important;
  caret-color:#a9852e!important;
  border:1px solid #222a2c!important;
  font-family:'Noto Serif SC','PingFang SC',serif!important
}
#ai-chat-input::placeholder,#ai-chat-bottom-input::placeholder,textarea.rc-textarea::placeholder{color:#8b8f8c!important;opacity:1!important}

/* ===== 全局 ===== 公文纸底 + 极淡网格纹理 */
body,html,#root,.app-root,.h-screen{
  background:#f1efe9!important;
  color:#222a2c!important
}
body{
  background-image:
    linear-gradient(rgba(43,66,96,0.045) 1px,transparent 1px),
    linear-gradient(90deg,rgba(43,66,96,0.045) 1px,transparent 1px),
    linear-gradient(180deg,#dfdbd0,#c9cdd4)!important;
  background-size:26px 26px,26px 26px,100% 100%!important;
  background-attachment:fixed!important
}

/* ===== 顶部导航 ===== 公文眉头:米白 + 墨线底 */
.sticky.w-full.top-0.flex.items-center{
  background:rgba(236,231,218,0.92)!important;
  border-bottom:3px solid #222a2c!important;
  backdrop-filter:blur(6px) saturate(1.05)!important
}
#ai-model-selector .group.flex.items-center{color:#222a2c!important}
#ai-model-selector .group.flex.items-center:hover{color:#a9852e!important}
#ai-model-selector .truncate.text-\[13px\]{color:#6a7176!important}
#ai-model-selector .shrink-0.flex.items-center svg{fill:#8b8f8c!important}
#ai-model-selector .shrink-0.flex.items-center:hover svg{fill:#a9852e!important}
#header-setting-button{color:#8b8f8c!important}
#header-setting-button:hover{color:#a9852e!important}

/* ===== 开场白区域 ===== */
div.flex.items-center.h-9.bg-white.rounded-md.cursor-pointer.group[class*="border-gray"]{
  background:#fbfaf7!important;
  border:1px solid #222a2c!important;
  border-radius:0!important;
  color:#222a2c!important
}
div.flex.items-center.h-9.cursor-pointer.group svg[data-icon="SlidersH"]{fill:#a9852e!important}
div.flex.items-center.h-9.cursor-pointer.group svg[data-icon="ChevronDown"]{fill:#8b8f8c!important}

/* ===== 侧边栏 ===== */
.shadow-lg.border-r.border-gray-200{
  background:#dfdbd0!important;
  border-right:2px solid #222a2c!important
}
.MuiList-root{background:transparent!important;color:#222a2c!important}
.conversation-text{color:#6a7176!important}

/* ===== 功能按钮 ===== */
#ai-mod-button2{background:transparent!important}
#ai-mod-button2 button.MuiButton-root{
  background:#c9cdd4!important;
  color:#222a2c!important;
  border:1px solid #222a2c!important;
  border-radius:0!important;
  transition:background 0.15s ease!important
}
#ai-mod-button2 button.MuiButton-root:hover{background:rgba(169,133,46,0.08)!important}
#ai-mod-button2 button.MuiButton-root svg{fill:#a9852e!important}

/* ===== 聊天气泡 ===== AI 每条回复 = 一页公文:公文纸底 + 墨全框 + 顶部藏青线 */
.bg-gray-100\/90.relative.inline-block{
  background:#fbfaf7!important;
  border:1px solid #222a2c!important;
  border-top:3px solid #2b4260!important;
  border-radius:0!important;
  padding:16px 18px!important;
  box-shadow:2px 2px 0 rgba(34,42,44,0.10)!important;
  transition:box-shadow 0.18s ease,border-color 0.18s ease!important;
  line-height:1.9!important
}
.bg-gray-100\/90.relative.inline-block:hover{
  border-color:#a9852e!important;
  box-shadow:3px 3px 0 rgba(169,133,46,0.20)!important
}
.bg-gray-100\/90.relative.inline-block:not(.chat-answer-container .bg-gray-100\/90){
  background:#dfdbd0!important
}

.markdown-body{
  color:#222a2c!important;
  font-size:1.3em!important;
  line-height:1.9!important;
  font-family:'Noto Serif SC','Source Han Serif SC','PingFang SC',serif!important;
  text-shadow:none!important
}
/* h1/h2/h3 = 公文标题:重衬线 + 朱砂红 + 下方藏青线分隔 */
.markdown-body h1,.markdown-body h2,.markdown-body h3,.markdown-body h4{
  color:#a9852e!important;
  font-family:'Noto Serif SC',serif!important;
  border-bottom:3px solid #2b4260!important;
  padding-bottom:6px!important;
  font-weight:900!important;
  letter-spacing:0.04em!important
}
.markdown-body h1{font-size:1.46em!important;text-align:center!important}
.markdown-body h2{font-size:1.26em!important}
.markdown-body h3{font-size:1.1em!important;color:#222a2c!important}
.markdown-body ul,.markdown-body ol,.markdown-body li{color:inherit!important;line-height:1.9!important}
.markdown-body ul li::marker{color:#a9852e!important}

/* 亮点① blockquote —— 校园广播 / 议论:上下藏青双线 + 斜体 + 朱砂点睛,无竖条 */
.markdown-body blockquote{
  position:relative!important;
  border:none!important;
  border-top:3px double #2b4260!important;
  border-bottom:3px double #2b4260!important;
  border-radius:0!important;
  background:transparent!important;
  color:#1d2f47!important;
  font-family:'Noto Serif SC',serif!important;
  font-style:italic!important;
  font-weight:700!important;
  text-align:center!important;
  font-size:1.04em!important;
  line-height:1.5!important;
  padding:14px 22px!important;
  margin:16px 4px!important
}
.markdown-body blockquote::before{
  content:'\201C'!important;
  position:absolute!important;
  left:6px!important;top:-2px!important;
  font-size:2em!important;
  font-family:Georgia,serif!important;
  color:#a9852e!important;
  opacity:0.7!important;
  pointer-events:none!important
}
.markdown-body blockquote p{margin:0!important}
.markdown-body blockquote strong,.markdown-body blockquote em{color:#a9852e!important;background:none!important}

/* 表格 —— 公文数据表:墨全框 + 藏青表头反白 */
.markdown-body table{
  border-collapse:collapse!important;
  margin:10px 0!important;
  font-size:0.86em!important
}
.markdown-body table th,.markdown-body table td{
  border:1px solid #222a2c!important;
  padding:7px 12px!important
}
.markdown-body table th{
  background:#2b4260!important;
  color:#f1efe9!important;
  font-weight:900!important;
  letter-spacing:0.06em!important
}
.markdown-body table tr:nth-child(even) td{background:#dfdbd0!important}

/* strong / em / a */
.markdown-body strong{
  color:#a9852e!important;
  font-weight:900!important;
  background:linear-gradient(180deg,transparent 70%,rgba(169,133,46,0.16) 70%,rgba(169,133,46,0.16) 94%,transparent 94%)!important;
  padding:0 2px!important
}
.markdown-body em,.markdown-body i{color:#353f42!important;font-style:italic!important}
.markdown-body a{color:#a9852e!important;text-decoration:underline!important;text-decoration-style:double!important}
.markdown-body a:hover{color:#8a6c22!important}
.markdown-body hr{
  border:none!important;
  height:4px!important;
  border-top:1px solid #222a2c!important;
  border-bottom:1px solid #222a2c!important;
  background:transparent!important;
  margin:16px 0!important
}

/* ═══════════════════════════════════════════════
   组件层 · 亮点① .sys ——【叮】系统通告条
   AI 输出 <div class="sys"><b>【叮】</b>通告内容</div>
   只在有系统事件时出现(改字生效/性交+1/额度刷新),插在正文事件处
   造型: 网文系统弹窗 · 面板白底 + 墨全框 + 顶部鎏金线 + 右上 SYSTEM 角标
   ═══════════════════════════════════════════════ */
.markdown-body .sys{
  position:relative!important;
  background:#fbfaf7!important;
  border:1px solid #222a2c!important;
  border-top:4px solid #a9852e!important;
  border-radius:0!important;
  margin:14px 0!important;
  padding:12px 14px 11px!important;
  box-shadow:3px 3px 0 rgba(169,133,46,0.16)!important;
  color:#222a2c!important;
  font-weight:700!important;
  line-height:1.7!important
}
.markdown-body .sys::after{
  content:'SYSTEM'!important;
  position:absolute!important;
  right:-1px!important;top:-1px!important;
  background:#a9852e!important;
  color:#fbfaf7!important;
  font-size:0.56em!important;
  font-weight:900!important;
  letter-spacing:0.18em!important;
  padding:2px 7px!important;
  opacity:0.9!important;
  pointer-events:none!important
}
.markdown-body .sys b,.markdown-body .sys strong{
  color:#a9852e!important;
  background:none!important;
  padding:0!important;
  font-weight:900!important;
  letter-spacing:0.06em!important
}

/* .sysbar —— 每轮仪表条: 📅天数·时间·地点 ｜ ✒额度 ｜ 💉性交数 */
.markdown-body .sysbar{
  background:#2b4260!important;
  color:#f4f1e8!important;
  border:1px solid #222a2c!important;
  border-radius:0!important;
  margin:16px 0 10px!important;
  padding:9px 13px!important;
  font-size:0.9em!important;
  font-weight:800!important;
  letter-spacing:0.05em!important;
  line-height:1.7!important;
  box-shadow:2px 2px 0 rgba(34,42,44,0.14)!important
}

/* ═══════════════════════════════════════════════
   组件层 · 亮点④ .tk —— 词条面板(网文系统状态栏 · 每轮展开)
   AI 输出 <div class="tk"> + 词条行 <div class="tk-r"><b>词条名</b><span>值</span></div>
   被玩家改过的字用 <mark>字</mark> 金高亮永久标出 · .tk-log=修改痕迹行
   .tk-me=玩家自己(金顶) · .tk-sec=秘密行 · .tk-live=活词条行 · .tk-in=已性交标
   ⚠️ 无左侧竖条 · 可读性第一: label 定宽淡色不加框,value 深墨
   ═══════════════════════════════════════════════ */
.markdown-body .tk{
  position:relative!important;
  background:#fbfaf7!important;
  border:1px solid #222a2c!important;
  border-top:4px solid #2b4260!important;
  border-radius:0!important;
  margin:16px 0!important;
  padding:0 0 4px!important;
  overflow:hidden!important;
  box-shadow:3px 3px 0 rgba(43,66,96,0.14)!important
}
.markdown-body .tk-h{
  background:#2b4260!important;
  color:#f4f1e8!important;
  font-weight:900!important;
  letter-spacing:0.1em!important;
  font-size:0.94em!important;
  padding:9px 14px!important;
  margin:0 0 4px!important
}
.markdown-body .tk-h i,.markdown-body .tk-h .tk-in{
  font-style:normal!important;
  background:#a9852e!important;
  color:#fbfaf7!important;
  font-size:0.66em!important;
  font-weight:900!important;
  letter-spacing:0.14em!important;
  padding:2px 7px!important;
  margin-left:8px!important;
  vertical-align:2px!important
}
.markdown-body .tk.tk-me{
  border-top-color:#a9852e!important;
  box-shadow:3px 3px 0 rgba(169,133,46,0.14)!important
}
.markdown-body .tk.tk-me .tk-h{background:#8a6c22!important}
.markdown-body .tk-r{
  display:flex!important;
  align-items:baseline!important;
  padding:7px 14px!important;
  margin:0!important;
  border-bottom:1px dashed rgba(34,42,44,0.22)!important;
  line-height:1.68!important
}
.markdown-body .tk-r:last-of-type{border-bottom:none!important}
.markdown-body .tk-r b{
  flex:0 0 4.4em!important;
  color:#6a7176!important;
  background:none!important;
  padding:0!important;
  font-size:0.82em!important;
  font-weight:900!important;
  letter-spacing:0.3em!important
}
.markdown-body .tk-r span{
  flex:1!important;
  color:#222a2c!important;
  font-weight:600!important;
  min-width:0!important;
  overflow-wrap:break-word!important;
  word-break:break-word!important
}
.markdown-body .tk-r.tk-sec b{color:#a9852e!important}
.markdown-body .tk-r.tk-sec span{color:#8a6c22!important}
.markdown-body .tk-r.tk-x b{color:#2b4260!important;font-weight:900!important}
.markdown-body .tk-r.tk-x span{color:#2b4260!important;font-weight:700!important}
.markdown-body .tk-r.tk-live b{color:#8b8f8c!important;font-weight:700!important}
.markdown-body .tk-r.tk-live span{color:#353f42!important;font-weight:500!important}
.markdown-body .tk-log{
  color:#8a6c22!important;
  background:rgba(169,133,46,0.08)!important;
  border-top:1px solid rgba(169,133,46,0.4)!important;
  font-size:0.8em!important;
  letter-spacing:0.04em!important;
  padding:7px 14px 6px!important;
  margin:4px 0 0!important;
  line-height:1.65!important
}

/* mark —— 被玩家改过的字 · 全卡最高优先级视觉 · 永久保留 */
.markdown-body mark{
  background:#f3e6c3!important;
  color:#7a5c1a!important;
  font-weight:900!important;
  padding:0 3px!important;
  border-bottom:2px solid #a9852e!important
}

/* ═══════════════════════════════════════════════
   组件层 · 亮点⑤ .led ——【⚡异能系统状态栏】全量账本(每轮必出 · 只增不减)
   AI 输出 <details open class="led"> + 两段 <ol class="led-list">
   造型: 系统账本 · 墨蓝 summary + 编号徽章(CSS counter · AI 只列 li 不手动编号)
   ⚠️ 无左侧竖条 · 修改记录=金徽章 · 性交记录 .led-inj=墨蓝徽章
   ═══════════════════════════════════════════════ */
.markdown-body details.led{
  background:#fbfaf7!important;
  border:1px solid #222a2c!important;
  border-top:4px solid #a9852e!important;
  border-radius:0!important;
  margin:14px 0!important;
  padding:0!important;
  overflow:hidden!important;
  box-shadow:3px 3px 0 rgba(169,133,46,0.14)!important
}
.markdown-body details.led>summary{
  background:#2b4260!important;
  color:#f4f1e8!important;
  font-weight:900!important;
  letter-spacing:0.08em!important;
  font-size:0.92em!important;
  padding:9px 14px 9px 34px!important;
  border:none!important;
  margin:0!important
}
.markdown-body .led-h{
  color:#8a6c22!important;
  background:rgba(169,133,46,0.08)!important;
  border-top:1px solid rgba(169,133,46,0.4)!important;
  border-bottom:1px dashed rgba(169,133,46,0.35)!important;
  font-size:0.8em!important;
  font-weight:900!important;
  letter-spacing:0.2em!important;
  padding:6px 14px 5px!important;
  margin:0!important
}
.markdown-body ol.led-list{
  list-style:none!important;
  counter-reset:led!important;
  margin:0!important;
  padding:8px 14px 6px!important
}
.markdown-body ol.led-list li{
  counter-increment:led!important;
  position:relative!important;
  margin:0 0 6px!important;
  padding:2px 2px 6px 36px!important;
  border-bottom:1px dashed rgba(34,42,44,0.16)!important;
  color:#222a2c!important;
  font-size:0.88em!important;
  font-weight:600!important;
  line-height:1.66!important
}
.markdown-body ol.led-list li:last-child{border-bottom:none!important;margin-bottom:0!important}
.markdown-body ol.led-list li::before{
  content:counter(led)!important;
  position:absolute!important;
  left:0!important;top:1px!important;
  width:22px!important;height:22px!important;
  display:flex!important;
  align-items:center!important;
  justify-content:center!important;
  background:#a9852e!important;
  color:#fbfaf7!important;
  font-size:0.72em!important;
  font-weight:900!important;
  border-radius:0!important
}
.markdown-body ol.led-list.led-inj li::before{background:#2b4260!important}
.markdown-body ol.led-list li.led-none{
  padding-left:2px!important;
  color:#8b8f8c!important;
  font-weight:500!important;
